/* theme */
const root=document.documentElement,tg=document.getElementById('tg');
function setTheme(t){root.dataset.theme=t;try{localStorage.setItem('theme',t)}catch(e){}}
let saved=null;try{saved=localStorage.getItem('theme')}catch(e){}
setTheme(saved||'dark');
tg.onclick=()=>{root.classList.add('tt');setTimeout(()=>root.classList.remove('tt'),450);setTheme(root.dataset.theme==='dark'?'light':'dark')};
document.getElementById('yr').textContent=new Date().getFullYear();

/* scroll reveal */
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.12});
document.querySelectorAll('.rv').forEach(el=>io.observe(el));

/* 3D tilt (mouse devices only) */
if(matchMedia('(hover:hover)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches){
  document.querySelectorAll('.tilt').forEach(c=>{
    c.addEventListener('mousemove',e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;
      c.style.setProperty('--mx',(x+.5)*100+'%');c.style.setProperty('--my',(y+.5)*100+'%');c.style.transform=`perspective(900px) rotateY(${x*(c.id==='ph'?9:c.classList.contains('pj')?5:14)}deg) rotateX(${-y*(c.id==='ph'?9:c.classList.contains('pj')?5:14)}deg) scale(1.03)`});
    c.addEventListener('mouseleave',()=>c.style.transform='');
  });
}

/* contact form: set your Formspree ID below (formspree.io), else it opens your email app */
const FORM_ID='xbggoqlb',MAIL='nitinchoure2006@gmail.com';
document.getElementById('form').addEventListener('submit',async e=>{
  e.preventDefault();const f=e.target,fs=document.getElementById('fs'),d=Object.fromEntries(new FormData(f));
  if(FORM_ID==='YOUR_FORM_ID'){
    location.href=`mailto:${MAIL}?subject=${encodeURIComponent('Portfolio message from '+d.name)}&body=${encodeURIComponent(d.message+'\n\n'+d.name+' ('+d.email+')')}`;
    fs.textContent='Opening your email app…';return;}
  fs.textContent='Sending…';
  try{const r=await fetch('https://formspree.io/f/'+FORM_ID,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify(d)});
    if(r.ok){fs.textContent='Message sent. Nitin will reply soon.';f.reset()}else throw 0}
  catch(x){fs.textContent='Could not send. Please email '+MAIL+' directly.'}
});

