const msgs=document.getElementById('msgs'),qs=document.getElementById('qs'),ci=document.getElementById('ci'),cbw=document.getElementById('cbw');
const add=(t,c)=>{const d=document.createElement('div');d.className='m '+c;if(c==='b'){d.innerHTML=t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/(https?:\/\/[^\s]+)/g,'<a href="$1" target="_blank" rel="noopener" style="color:var(--blue);text-decoration:underline;word-break:break-all">$1</a>').replace(/\n/g,'<br>')}else d.textContent=t;msgs.appendChild(d);msgs.scrollTop=msgs.scrollHeight};
const STOP=new Set('a an the is are am do does did you your yours me my i can could would will what which whom how why where when of to in on at for and or with about tell please this that it be have has any there their his him he nitin'.split(' '));
const stem=w=>w.replace(/(ing|ies|es|s)$/,'').replace(/y$/,'i');
const toks=t=>t.toLowerCase().replace(/[^a-z0-9+ ]/g,' ').split(/\s+/).filter(w=>w&&!STOP.has(w)).map(stem);
const QT=QA.map(x=>({q:new Set(toks(x.q)),a:new Set(toks(x.a))}));
function reply(q){
  if(/^\s*(hi+|hello|hey|namaste)\b/i.test(q)&&q.trim().split(/\s+/).length<4)return"Hi! I can answer questions about Nitin's education, skills, projects, internship goals, strengths and how to contact him. Tap a topic below or type your question.";
  const t=toks(q);if(!t.length)return QA[60].a;
  let best=-1,sc=0;
  QT.forEach((x,i)=>{let s=0;t.forEach(w=>{if(x.q.has(w))s+=2;else if(x.a.has(w))s+=.6});s=s/Math.sqrt(1+x.q.size*.25);if(s>sc){sc=s;best=i}});
  if(best<0||sc<1)return QA[60].a;
  const r=QA[best];return/resume|cv/i.test(r.q)?{t:r.a,dl:1}:r.a;}
function addDl(){const d=document.createElement('div');d.className='m b';const bt=document.createElement('button');bt.textContent='Download resume (PDF)';bt.style.cssText='background:var(--blue);color:#04281c;border:0;border-radius:10px;padding:9px 14px;font-weight:700;cursor:pointer';bt.onclick=()=>dlResume();d.appendChild(bt);msgs.appendChild(d);msgs.scrollTop=msgs.scrollHeight}
function ask(q,label){if(!q.trim())return;add(label||q,'u');setTimeout(()=>{const r=reply(q);add(r.t||r,'b');if(r.dl)addDl()},350)}
