/* resume download (PDF embedded in the page, works without a separate file) */
const RESUME_B64="";
function dlResume(){try{const bin=atob(RESUME_B64),u8=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)u8[i]=bin.charCodeAt(i);const blob=new Blob([u8],{type:'application/pdf'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Nitin_Choure_Resume.pdf';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);if(/iP(hone|ad|od)/.test(navigator.userAgent))setTimeout(()=>window.open(url,'_blank'),300)}catch(e){alert('Could not download the resume. Please contact me by email.')}}
document.querySelectorAll('[data-dl=resume]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();dlResume()}));
/* count-up numbers */
const co=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;co.unobserve(e.target);const el=e.target,to=+el.dataset.to,d=+el.dataset.dec,t0=performance.now();
  (function f(t){const p=Math.min((t-t0)/1400,1);el.textContent=(to*(1-Math.pow(1-p,3))).toFixed(d);if(p<1)requestAnimationFrame(f)})(t0)}),{threshold:.6});
