  groups.forEach(([sel])=>$(sel).forEach((el,i)=>{
    el.classList.add('sr');
    el.style.setProperty('--d',(i%4)*.1+'s');
    el.style.setProperty('--sx',sel==='.ed'||sel==='.xp'?(i%2?'40px':'-40px'):'0px');
    el.style.setProperty('--sy',sel==='.ed'||sel==='.xp'?'20px':'40px');
  }));
  let wi=0;const split=n=>{[...n.childNodes].forEach(c=>{if(c.nodeType===3){const f=document.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(t=>{if(!t)return;if(/^\s+$/.test(t)){f.appendChild(document.createTextNode(' '));return}const w=document.createElement('span');w.className='w';const i=document.createElement('span');i.className='wi';i.style.setProperty('--i',wi++);i.textContent=t;w.appendChild(i);f.appendChild(w)});c.replaceWith(f)}else if(c.nodeType===1)split(c)})};
  $('main section h2').forEach(h=>{wi=0;h.setAttribute('aria-label',h.textContent);split(h);h.classList.add('hd')});
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in')}else if(!LOW){const el=e.target;if(el.classList.contains('sr')&&!el.classList.contains('hd')){const a=Math.abs(parseFloat(el.style.getPropertyValue('--sy'))||40);el.style.setProperty('--sy',(e.boundingClientRect.top<0?-a:a)+'px')}el.classList.remove('in')}}),{threshold:LOW?0:.12,rootMargin:LOW?'0px 0px 12% 0px':'0px 0px -6% 0px'});
  $('.sr,.sh,.hd').forEach(el=>io.observe(el));
  // sections replay both directions
  const io2=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on')}else if(!LOW)e.target.classList.remove('on')}),{threshold:0,rootMargin:LOW?'0px 0px 12% 0px':'0px 0px -8% 0px'});
  $('.rv').forEach(el=>io2.observe(el));
